"""Build a reproducible PM report from the final Phase 2.2 ledgers."""
from __future__ import annotations
import argparse,csv,json
from collections import Counter,defaultdict
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def lines(p):return [json.loads(s) for s in p.read_text(encoding='utf-8').splitlines() if s.strip()]
def loadcsv(p):
 with p.open(newline='',encoding='utf-8') as f:return list(csv.DictReader(f))
def fmt(c):return ', '.join(f'{k}: {v}' for k,v in sorted(c.items()))
def build(out:Path,report:Path):
 refs=loadcsv(out/'creative_mechanism_phase2_2_reference_master.csv');scenes=lines(out/'creative_mechanism_phase2_2_fullpage_scene_evidence.jsonl');snaps=lines(out/'creative_mechanism_phase2_2_snapshots.jsonl');risks=lines(out/'creative_mechanism_phase2_2_risk_missingness.jsonl');claims=lines(out/'creative_mechanism_phase2_2_claim_ledger.jsonl');fails=lines(out/'creative_mechanism_phase2_2_capture_failures.jsonl');candidates=lines(out/'creative_mechanism_phase2_2_mechanism_candidates.jsonl');dups=lines(out/'creative_mechanism_phase2_2_duplicate_map.jsonl');coverage=loadcsv(out/'creative_mechanism_phase2_2_coverage_matrix.csv');runtime=lines(out/'creative_mechanism_phase2_2_runtime_observations.jsonl');semantic=lines(out/'creative_mechanism_phase2_2_semantic_job_coverage.jsonl');qa=json.loads((out/'creative_mechanism_phase2_2_qa_report.json').read_text());registry=json.loads((out/'archive_registry.json').read_text())
 cap=Counter(str(x.get('http_status') or x.get('error','NO_HTTP_STATUS').split(':')[0]) for x in fails)
 scene_state=Counter(x['observation_state'] for x in scenes);scene_jobs=Counter()
 for x in scenes:
  js=x.get('scene_job') or [];js=[js] if isinstance(js,str) else js
  if x.get('observation_state')=='OBSERVED':scene_jobs.update(js)
 source=Counter(x['discovery_source_class'] for x in refs);market=Counter(x['market_scope'] for x in refs);pool=Counter(x['pool_type'] for x in refs);archetype=Counter(x['business_archetype'] for x in refs);industry=Counter(x['industry'] for x in refs);archive_by_market=defaultdict(Counter)
 for x in refs:archive_by_market[x['market_scope']][x['archive_status']]+=1
 gold15=set(json.loads((ROOT/'config/phase2_2_fullpage_capture_targets.json').read_text())['gold15_backfill'])
 gold_existing={'P01-R01','P05-R04','P06-R02','P08-R02','P12-R01'}
 full_capture={x['reference_id'] for x in refs if x['desktop_fullpage_state']=='CAPTURED' and x['mobile_fullpage_state']=='CAPTURED'}|gold_existing
 archive_rows=[x for x in registry if x['archive_id']!='GOLD20-FULLPAGE-V1']
 sample_ids={'CUSTOMER_CASE_PROOF':'P22-P03-R01-DESKTOP-SCENE-002','MULTI_ITEM_SERVICE_CLUSTER':'GOLD-P06-R02-DESKTOP-TRAV-02','MULTI_PATH_CTA':'P22-P03-R04-DESKTOP-SCENE-002','PRICING_COMPARISON':'P22-P11-R03-DESKTOP-SCENE-004','QUESTION_ANSWER_CLUSTER':'P22-P11-R03-DESKTOP-SCENE-008','TRUST_DISCLOSURE_LIST':'P22-P05-R01-DESKTOP-SCENE-006'}
 mobile_ids={'CUSTOMER_CASE_PROOF':'P22-P03-R01-MOBILE-SCENE-003','MULTI_ITEM_SERVICE_CLUSTER':'GOLD-P06-R02-MOBILE-TRAV-02','MULTI_PATH_CTA':'P22-P03-R04-MOBILE-SCENE-002','PRICING_COMPARISON':'P22-P11-R03-MOBILE-SCENE-005','QUESTION_ANSWER_CLUSTER':'P22-P11-R03-MOBILE-SCENE-009','TRUST_DISCLOSURE_LIST':'P22-P05-R01-MOBILE-SCENE-006'}
 scene_map={x['scene_evidence_id']:x for x in scenes};cand_map={x['mechanism_name']:x for x in candidates}
 mobile_rules={'CUSTOMER_CASE_PROOF':'390pxでは施工事例カードを縦に積み、写真・物件名の順を保つ。','MULTI_ITEM_SERVICE_CLUSTER':'390pxでは診療科目が縦の開閉リストへ再配置される。項目名を残し、画面横幅に依存する列数は引き継がない。','MULTI_PATH_CTA':'390pxでは相談・検索の3選択肢が縦カードになり、各カードの目的と個別CTAを維持する。','PRICING_COMPARISON':'390pxでは料金3プランを縦積みにし、プラン名・月額・CTAを各カード内で保持する。','QUESTION_ANSWER_CLUSTER':'390pxではFAQ行を縦並びにする。開閉動作自体は未テストなので静的構造だけを移植対象にする。','TRUST_DISCLOSURE_LIST':'390pxでは日付付きのお知らせを一列に並べ、各項目の見出しと遷移手掛かりを保つ。'}
 sections=[]
 sections.append('# Creative Mechanism Database — Phase 2.2 100-Reference Pilot Report\n')
 sections.append('**Status:** `PHASE_2_2_100_REFERENCE_PILOT_READY_FOR_PM_REVIEW`  \n**SSOT:** Issue #143 / Sarah PM Comment #5888589418  \n**Architecture:** v1.3.1  \n**Capture Run:** `36558472328` / temporary Artifact `11028964368` (`sha256:7c32d38a9cfc16108c0e65b522b93e9b903355d877e96b5705363f7f31eb22aa`)\n')
 sections.append('## Decision and scope\n\nAll original 100 pilot records remain in the master ledger and all 20 coverage cells retain five references each. The 15 remaining Gold references received full-page backfill. Five already traversed Gold references retain their v1.3.1 evidence and archive provenance. There are **100 uniform ledger records**, but **27 references still lack visual captures** because the official site returned an error or denied access at both viewports. Their durable capture-failure records are linked; these references remain `HOLD`. No score, Strong promotion, or mechanism promotion was made from missing or unobserved evidence. The 2,600-reference gate remains `false`.\n')
 sections.append('## Coverage and observation\n\n| Measure | Result |\n|---|---:|\n| References / preserved cells | 100 / 20 × 5 |\n| JP / Global | '+str(market['JP'])+' / '+str(market['GLOBAL'])+' |\n| Pool: Conversion / Creative Benchmark | '+str(pool['CONVERSION_INDUSTRY'])+' / '+str(pool['CREATIVE_BENCHMARK'])+' |\n| Industries / business archetypes represented | '+str(len(industry))+' / '+str(len(archetype))+' |\n| Gold 15 full-page backfill | 15 / 15 both viewports captured |\n| References with durable 1440 + 390 screenshot evidence | '+str(sum(x['archive_status']=='DURABLE_VERIFIED' for x in refs))+' / 100 |\n| References with both viewport screenshots unavailable | '+str(sum(x['archive_status']!='DURABLE_VERIFIED' for x in refs))+' / 100 |\n| Scene rows / OBSERVED / NOT_OBSERVED | '+str(len(scenes))+' / '+str(scene_state['OBSERVED'])+' / '+str(scene_state['NOT_OBSERVED'])+' |\n| Semantic-job coverage rows | '+str(len(semantic))+' (100 × 2 viewports; six jobs each) |\n| Runtime / accessibility observation rows | '+str(len(runtime))+' (runtime behaviors remain NOT_OBSERVED unless independently tested) |\n| Explicit capture-failure records | '+str(len(fails))+' |\n\n`NOT_APPLICABLE` was not assigned merely because a keyword was absent. If the captured DOM and pixels did not support a positive scene classification, the job remains `NOT_OBSERVED` pending human semantic review. Scene/job coverage by matrix cell is in `data/creative_mechanism_phase2_2_coverage_matrix.csv`.\n')
 sections.append('### Matrix cells\n\n| Cell | Archetype | Industry | Market | Discovery source | Durable both views | Scenes | Observed | Not observed |\n|---|---|---|---|---|---:|---:|---:|---:|\n')
 for x in coverage:sections.append(f"| {x['slot_id']} | {x['business_archetype']} | {x['industry']} | {x['market_scope']} | {x['discovery_source_class']} | {x['both_viewports_durable_count']} / 5 | {x['scene_count']} | {x['observed_scene_count']} | {x['not_observed_scene_count']} |\n")
 sections.append('\n### Discovery mix and capture failures\n\nDiscovery mix (counts): '+fmt(source)+'.\n\nCapture-failure response/status mix (54 viewport attempts): '+fmt(cap)+'.\n\nFailures affect 27 complete reference pairs. They include HTTP 403/404/405/429/502, response pages with no usable content, timeout, and HTTP/2 protocol errors. `creative_mechanism_phase2_2_capture_failures.jsonl` records each URL, viewport, HTTP status/error, and durable capture-manifest locator. No blocked page was bypassed.\n')
 sections.append('\n| Market | Durable both views | Partial / missing |\n|---|---:|---:|\n')
 for m,c in sorted(archive_by_market.items()):sections.append(f"| {m} | {c['DURABLE_VERIFIED']} | {c['PARTIAL_DURABLE_HOLD']} |\n")
 sections.append('\n## Evidence Archive\n\nThe 95-reference capture was packaged in 10 immutable-by-version Library ZIPs. Each is pinned to `file_id` / version 0, is retrievable through its actual Library locator, and was re-downloaded for byte-for-byte Container SHA verification. All image/member hashes were checked against the archive index. The five earlier Full-page Gold references retain the preexisting `GOLD20-FULLPAGE-V1` archive. Repository stores manifests and indices only, not screenshot binaries.\n\n| Archive | File | Bytes | SHA-256 |\n|---|---|---:|---|\n')
 for x in archive_rows:sections.append(f"| {x['archive_id']} | `{x['file_name']}` | {x.get('file_size_bytes','')} | `{x['container_sha256']}` |\n")
 sections.append('\nNew archive batches contain '+str(sum(1 for x in lines(out/'creative_mechanism_phase2_2_archive_index.jsonl') if x.get('archive_id')!='GOLD20-FULLPAGE-V1' and x.get('content_type')!='CAPTURE_ATTEMPT_MANIFEST'))+' screenshot/crop members and durable attempt manifests. All 54 unavailable viewport attempts point to the exact archived `manifest_subset.json` entry and its SHA-256. Retention policy is three years after last mechanism use with yearly review; monthly retrieval/hash verification, recapture on URL/page change, and fail-closed `HOLD` on archive loss are recorded per archive in `creative_mechanism_phase2_2_archive_registry.json`. The storage backend does not provide a claimed retention SLA.\n')
 sections.append('\n## Mechanism synthesis\n\nExtraction used only `OBSERVED` scenes with a concrete locator, archived crop, and pinned archive. Candidate source IDs and counts are derived from `source_scene_evidence_ids[]`; no evidence from `NOT_OBSERVED`, `MISSING`, or `NOT_APPLICABLE` scenes is eligible. Candidate definitions were narrowed after checking both desktop and mobile crops. Confidence remains `HEURISTIC_NEEDS_PIXEL_REVIEW`; each remains `CANDIDATE`, not `SUPPORTED` or `CANONICAL`.\n\n| Candidate | Scene evidence | Refs / brands | Desktop sample | Mobile sample | Mobile transfer rule |\n|---|---:|---:|---|---|---|\n')
 for name,c in cand_map.items():
  sid=sample_ids[name];mid=mobile_ids[name];s=scene_map[sid];m=scene_map[mid]
  sections.append(f"| `{name}` | {c['evidence_count']} | {c['reference_count']} / {c['unique_brand_count']} | `{sid}` — {s['reference_id']}, {s['concrete_locator'][:70]} | `{mid}` — {m['reference_id']}, {m['concrete_locator'][:70]} | {mobile_rules[name]} |\n")
 sections.append('\nAcross these six mined families: **'+str(len(candidates))+' exact rule families / '+str(sum(c['evidence_count'] for c in candidates))+' scene links / '+str(len({r for c in candidates for r in c['reference_lps']}))+' distinct reference sources**. The duplicate map contains exact family identifiers and non-automatic variant-review edges; possible variants are not merged by text similarity alone. Co-observed pairs are not marked compatible.\n\n**Status of older candidates:** existing 20 Gold candidates, 15 Phase 2.1.1 candidates, and 25 `PROVISIONAL_FROM_PHASE2` records are preserved in `creative_mechanism_phase2_2_frozen_legacy_candidates.jsonl` (60 total). They were not automatically affirmed or promoted.\n')
 sections.append('\n## Scores, claims, and runtime checks\n\nAll 100 full-page scores are `NOT_SCORED`; ranking and Strong / mechanism promotion flags are false. The 20 Gold legacy scores remain explicitly scoped to `CAPTURED_ENTRY_AND_FIRST_SCROLL_ONLY`. The other 80 legacy scores are `PROVISIONAL_UNAUDITED`. All 100 records remain `HOLD` pending PM review and unresolved record gates.\n\nThe claim ledger has '+str(len(claims))+' units. Visible numeric/outcome statements remain `VISIBLE_TEXT_ONLY_NOT_VERIFIED` or their inherited not-verified status; claim truth was not inferred. Finance/medical/beauty records remain subject to claim-unit review. Accessibility keyboard/focus/contrast/reduced-motion and runtime motion/performance were not tested, so they remain `NOT_OBSERVED` / `NOT_MEASURED`, never PASS.\n')
 sections.append('\n## QA result\n\n`validate_phase2_2.py`: **PASS**. Machine checks confirmed 100 unique references; 20 × 5 matrix preservation; desktop/mobile snapshot state for every reference; 200 semantic-job and 200 runtime rows; explicit missingness; 1,240 Scene rows; 1,442 indexed archive references (image members, attempt manifests, and preserved Gold archive); archive container/member integrity; observed-only provenance; derived candidate evidence/reference/brand counts; no duplicate canonical URLs; no unsupported promotion; scoped scores; and `bulk_collection_allowed = false`. Unit tests cover heading-anchored scene boundaries, semantic missingness, and observed + durable-only mechanism provenance.\n\n')
 sections.append('## Unresolved risks and stop point\n\n1. Twenty-seven references have no usable desktop/mobile pixels. Their durable HTTP/error records are retained; leave them `HOLD` until an approved accessible official page or fresh recapture can be reviewed.\n2. 100 / 100 design agencies and campaign families remain `UNKNOWN`; the pilot does not infer independence.\n3. Semantic-job absence is conservatively `NOT_OBSERVED` unless a reviewer confirms the scene is genuinely inapplicable.\n4. Motion, interaction behavior, runtime accessibility, and performance were not established by static captures.\n5. Mechanism families are pilot candidates. Broader pixel review and independent-reference/brand/agency gates remain before any promotion.\n6. The evidence Archive has actual Library locators and pinned file versions; backend long-term availability is not guaranteed. Monthly verification and fail-closed recovery are required.\n\n**Recommendation:** stop at PM review. Resolve or explicitly accept the 27 capture holds and inspect the candidate definitions/source crops before authorizing the next stage. **Do not begin the 2,600-reference universe.**\n')
 report.parent.mkdir(parents=True,exist_ok=True);report.write_text(''.join(sections),encoding='utf-8')
 print(json.dumps({'report':str(report),'references':len(refs),'scene_states':dict(scene_state),'failures':len(fails),'candidates':len(candidates),'archive_batches':len(archive_rows)},ensure_ascii=False))
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--output-dir',type=Path,required=True);p.add_argument('--report',type=Path,required=True);a=p.parse_args();build(a.output_dir,a.report)
